INSERT INTO player_character.feats (id, ruleset, slug, name_en, name, prerequisites, description, source, feat_type, mechanical_effects)
VALUES
    ('40000000-0000-0000-0000-000000000800', 'SRD_2024', 'crafter-2024', 'Crafter', 'Artesão', 'Nível 1 (Talento de Origem)', 'Você ganha proficiência com três ferramentas de artesão à sua escolha. Além disso, você recebe um desconto de 20% ao comprar itens não mágicos e pode criar itens durante um descanso com maior rapidez.', 'SRD', 'ORIGIN', '{"abilityBonuses": {}, "grantedProficiencies": ["FERRAMENTAS_ARTESANAIS"], "featType": "ORIGIN"}'::jsonb),
    ('40000000-0000-0000-0000-000000000801', 'SRD_2024', 'healer-2024', 'Healer', 'Curandeiro', 'Nível 1 (Talento de Origem)', 'Você tem o treinamento médico para tratar ferimentos rapidamente. Ao usar um kit de curandeiro em uma criatura, você pode gastar um uso do kit para permitir que ela gaste um dado de vida e recupere pontos de vida iguais à rolagem + seu modificador de Sabedoria.', 'SRD', 'ORIGIN', '{"abilityBonuses": {}, "actionName": "Tratamento M\u00e9dico", "actionType": "ACTION", "featType": "ORIGIN"}'::jsonb),
    ('40000000-0000-0000-0000-000000000802', 'SRD_2024', 'lucky-2024', 'Lucky', 'Sortudo', 'Nível 1 (Talento de Origem)', 'Você possui uma sorte inexplicável que parece intervir quando você mais precisa. Você tem um número de Pontos de Sorte igual ao seu bônus de proficiência, recuperados após um descanso longo. Você pode gastar pontos para ganhar vantagem em jogadas de d20 ou impor desvantagem em ataques contra você.', 'SRD', 'ORIGIN', '{"abilityBonuses": {}, "usesPerRest": 2, "restType": "LONG", "actionName": "Ponto de Sorte", "actionType": "FREE", "featType": "ORIGIN"}'::jsonb),
    ('40000000-0000-0000-0000-000000000803', 'SRD_2024', 'musician-2024', 'Musician', 'Músico', 'Nível 1 (Talento de Origem)', 'Você é praticante de música e canções revigorantes. Você ganha proficiência com três instrumentos musicais. Ao terminar um descanso curto ou longo, você pode tocar uma canção que concede Inspiração Heroica a um número de aliados igual ao seu bônus de proficiência.', 'SRD', 'ORIGIN', '{"abilityBonuses": {}, "grantedProficiencies": ["INSTRUMENTOS_MUSICAIS"], "actionName": "Can\u00e7\u00e3o de Inspira\u00e7\u00e3o Heroica", "actionType": "FREE", "featType": "ORIGIN"}'::jsonb),
    ('40000000-0000-0000-0000-000000000804', 'SRD_2024', 'tavern-brawler-2024', 'Tavern Brawler', 'Brigão de Taverna', 'Nível 1 (Talento de Origem)', 'Acostumado à pancadaria áspera com o que estiver à mão. Seus ataques desarmados causam 1d4 + mod Força de dano. Sempre que atingir uma criatura com um ataque desarmado em seu turno, você pode empurrá-la 1,5 metro de distância imediatamente.', 'SRD', 'ORIGIN', '{"abilityBonuses": {}, "diceFormula": "1d4", "actionName": "Empurr\u00e3o Desarmado", "actionType": "FREE", "featType": "ORIGIN"}'::jsonb),
    ('40000000-0000-0000-0000-000000000700', 'SRD_2024', 'athlete-2024', 'Athlete', 'Atleta', 'Nível 4+, Força ou Destreza 13+', 'Você passou por um treinamento físico intenso para alcançar o ápice atlético. Levantar-se quando estiver caído consome apenas 1,5 metro de movimento. Escalar não consome movimento extra e seus saltos à distância precisam de apenas 1,5 metro de corrida.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "STR_OR_DEX", "minValue": 13, "displayLabel": "For\u00e7a ou Destreza 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000701', 'SRD_2024', 'charger-2024', 'Charger', 'Investida Agressiva', 'Nível 4+, Força ou Destreza 13+', 'Ao correr pelo campo de batalha, seu ímpeto é devastador. Ao realizar a ação Correr, seu deslocamento aumenta em 3 metros adicionais. Se mover ao menos 3 metros em linha reta antes de acertar um ataque corpo a corpo, cause +1d8 de dano ou empurre o alvo 3 metros.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "diceFormula": "1d8", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000702', 'SRD_2024', 'crossbow-expert-2024', 'Crossbow Expert', 'Especialista em Besta', 'Nível 4+, Destreza 13+', 'Graças à prática extensiva com a besta, você ignora a propriedade de recarga das bestas com as quais é proficiente. Estar a até 1,5 metro de uma criatura hostil não impõe desvantagem em suas jogadas de ataque à distância com bestas.', 'SRD', 'GENERAL', '{"abilityBonuses": {"DEX": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "DEXTERITY", "minValue": 13, "displayLabel": "Destreza 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000703', 'SRD_2024', 'crusher-2024', 'Crusher', 'Esmagador', 'Nível 4+, Força ou Constituição 13+', 'Você pratica a arte de esmagar seus oponentes. Uma vez por turno, ao causar dano de concussão a uma criatura, você pode movê-la 1,5 metro para um espaço desocupado. Ao obter um acerto crítico com dano de concussão, jogadas de ataque contra o alvo têm vantagem até o início do seu próximo turno.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "CON"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000704', 'SRD_2024', 'defensive-duelist-2024', 'Defensive Duelist', 'Duelista Defensivo', 'Nível 4+, Destreza 13+', 'Quando você estiver empunhando uma arma de acuidade com a qual é proficiente e outra criatura atingir você com um ataque corpo a corpo, você pode usar sua reação para adicionar seu bônus de proficiência à sua CA contra aquele ataque.', 'SRD', 'GENERAL', '{"abilityBonuses": {"DEX": 1}, "grantsReaction": true, "actionName": "Aparar Duelista", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "DEXTERITY", "minValue": 13, "displayLabel": "Destreza 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000705', 'SRD_2024', 'dual-wielder-2024', 'Dual Wielder', 'Combatente com Duas Armas', 'Nível 4+, Força ou Destreza 13+', 'Você domina o combate com duas armas. Você ganha +1 de bônus na CA enquanto estiver empunhando uma arma corpo a corpo em cada mão. Você pode usar armas de uma mão que não possuam a propriedade leve no combate com duas armas, e pode sacar ou embainhar duas armas simultaneamente.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "acBonus": 1, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000706', 'SRD_2024', 'durable-2024', 'Durable', 'Robusto', 'Nível 4+, Constituição 13+', 'Robusto e resistente, você tem vantagem em salvaguardas contra a morte. Como ação bônus, você pode gastar um dos seus dados de vida para recuperar pontos de vida iguais à rolagem + modificador de Constituição uma vez por descanso.', 'SRD', 'GENERAL', '{"abilityBonuses": {"CON": 1}, "actionName": "Recupera\u00e7\u00e3o Robusta", "actionType": "BONUS_ACTION", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "CONSTITUTION", "minValue": 13, "displayLabel": "Constitui\u00e7\u00e3o 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000707', 'SRD_2024', 'elemental-adept-2024', 'Elemental Adept', 'Adepto Elemental', 'Nível 4+, Conjurador', 'Magias que você conjura ignoram resistência ao tipo de dano escolhido (Ácido, Frio, Fogo, Relâmpago ou Trovão). Além disso, ao rolar dano desse tipo para magias, qualquer 1 rolado em um dado conta como 2.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS", "CHA"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000708', 'SRD_2024', 'great-weapon-master-2024', 'Great Weapon Master', 'Mestre de Armas Grandes', 'Nível 4+, Força 13+', 'Você aprendeu a usar o peso de uma arma em seu benefício. Em seu turno, ao obter um acerto crítico com uma arma corpo a corpo ou reduzir uma criatura a 0 PV, você pode realizar um ataque com arma corpo a corpo como ação bônus. Além disso, ataques com armas pesadas causam dano extra igual ao seu bônus de proficiência.', 'SRD', 'GENERAL', '{"abilityBonuses": {"STR": 1}, "actionName": "Golpe Cortante Extra", "actionType": "BONUS_ACTION", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "STRENGTH", "minValue": 13, "displayLabel": "For\u00e7a 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000709', 'SRD_2024', 'heavy-armor-master-2024', 'Heavy Armor Master', 'Mestre de Armadura Pesada', 'Nível 4+, Proficiência com Armaduras Pesadas', 'Você pode usar sua armadura pesada para desviar de golpes contundentes. Enquanto veste armadura pesada, o dano cortante, perfurante e de concussão que você sofre de ataques não mágicos é reduzido em um valor igual ao seu bônus de proficiência.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "CON"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000710', 'SRD_2024', 'heavily-armored-2024', 'Heavily Armored', 'Armadura Pesada', 'Nível 4+, Proficiência com Armaduras Médias', 'Você treinou para usar armaduras pesadas e ganha proficiência com armaduras pesadas.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "CON"], "bonusAmount": 1}, "grantedProficiencies": ["ARMADURAS_PESADAS"], "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000711', 'SRD_2024', 'inspiring-leader-2024', 'Inspiring Leader', 'Líder Inspirador', 'Nível 4+, Sabedoria ou Carisma 13+', 'Você pode gastar 10 minutos inspirando seus companheiros. Escolha até seis criaturas amigáveis a até 9 metros. Cada criatura ganha pontos de vida temporários iguais ao seu nível + modificador de Sabedoria ou Carisma.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["WIS", "CHA"], "bonusAmount": 1}, "actionName": "Discurso Inspirador", "actionType": "ACTION", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000712', 'SRD_2024', 'keen-mind-2024', 'Keen Mind', 'Mente Aguçada', 'Nível 4+, Inteligência 13+', 'Você possui uma mente analítica aguçada. Você pode realizar a ação de Estudo como uma ação bônus em combate e ganha proficiência ou especialização em Arcana, História, Natureza, Religião ou Investigação.', 'SRD', 'GENERAL', '{"abilityBonuses": {"INT": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "INTELLIGENCE", "minValue": 13, "displayLabel": "Intelig\u00eancia 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000713', 'SRD_2024', 'mage-slayer-2024', 'Mage Slayer', 'Matador de Magos', 'Nível 4+', 'Você praticou técnicas contra conjuradores. Quando uma criatura a até 1,5 metro de você conjurar uma magia, você pode usar sua reação para fazer um ataque corpo a corpo contra ela. Ao causar dano a uma criatura que esteja se concentrando, ela tem desvantagem na salvaguarda de concentração.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "grantsReaction": true, "actionName": "Golpe Contra-Feiti\u00e7o", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000714', 'SRD_2024', 'medium-armor-master-2024', 'Medium Armor Master', 'Mestre de Armadura Média', 'Nível 4+, Proficiência com Armaduras Médias', 'Usar armadura média não impõe desvantagem em seus testes de Destreza (Furtividade), e o bônus máximo de Destreza que você pode aplicar à CA ao vestir armadura média aumenta para +3 (em vez de +2).', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000715', 'SRD_2024', 'moderately-armored-2024', 'Moderately Armored', 'Armadura Média', 'Nível 4+, Proficiência com Armaduras Leves', 'Você treinou para usar armaduras médias e escudos, ganhando proficiência com ambos.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "grantedProficiencies": ["ARMADURAS_MEDIAS", "ESCUDOS"], "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000716', 'SRD_2024', 'mounted-combatant-2024', 'Mounted Combatant', 'Combatente Montado', 'Nível 4+', 'Você é um guerreiro perigoso quando montado. Você tem vantagem em jogadas de ataque corpo a corpo contra qualquer criatura a pé que seja menor que sua montaria. Você pode forçar um ataque que alveje sua montaria a alvejar você em vez disso.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX", "WIS"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000717', 'SRD_2024', 'observant-2024', 'Observant', 'Observador', 'Nível 4+, Inteligência ou Sabedoria 13+', 'Rápido em notar detalhes no ambiente. Você pode realizar a ação Procurar como uma ação bônus. Além disso, se puder ver a boca de uma criatura enquanto ela fala um idioma que você entende, você pode ler seus lábios.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS"], "bonusAmount": 1}, "actionName": "Procurar (\u00c1gil)", "actionType": "BONUS_ACTION", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000718', 'SRD_2024', 'piercer-2024', 'Piercer', 'Perfurador', 'Nível 4+, Força ou Destreza 13+', 'Você atingiu grande precisão em combate perfurante. Uma vez por turno, ao acertar um ataque que causa dano perfurante, você pode jogar novamente um dos dados de dano da arma. Ao obter um acerto crítico perfurante, você rola um dado de dano adicional.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "criticalDiceBonus": 1, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000719', 'SRD_2024', 'polearm-master-2024', 'Polearm Master', 'Mestre de Armas de Haste', 'Nível 4+, Força ou Destreza 13+', 'Ao realizar a ação de Ataque empunhando uma glaive, alabarda, lança longa ou bordão, você pode usar uma ação bônus para desferir um ataque corpo a corpo com a outra extremidade da arma (dano de concussão 1d4). Criaturas provocam ataque de oportunidade ao entrar no seu alcance.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "actionName": "Golpe da Coronha", "actionType": "BONUS_ACTION", "diceFormula": "1d4", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000720', 'SRD_2024', 'resilient-2024', 'Resilient', 'Resiliente', 'Nível 4+', 'Escolha um atributo. Você aumenta o valor do atributo escolhido em 1 ponto e ganha proficiência em salvaguardas que utilizam o atributo escolhido.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX", "CON", "INT", "WIS", "CHA"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000721', 'SRD_2024', 'ritual-caster-2024', 'Ritual Caster', 'Conjurador de Rituais', 'Nível 4+, Inteligência, Sabedoria ou Carisma 13+', 'Você domina a arte de lançar rituais antigos. Escolha uma classe de conjurador: você pode conjurar rituais dessa classe usando seu atributo de conjuração. Uma vez por descanso longo, você pode conjurar uma magia de ritual com seu tempo normal de conjuração.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS", "CHA"], "bonusAmount": 1}, "spellChoice": {"cantripsCount": 0, "spellsCount": 2, "spellLevel": 1, "allowedClasses": ["BARD", "CLERIC", "DRUID", "SORCERER", "WARLOCK", "WIZARD"], "isRitualOnly": true}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000722', 'SRD_2024', 'sentinel-2024', 'Sentinel', 'Sentinela', 'Nível 4+, Força ou Destreza 13+', 'Você dominou técnicas para punir adversários que recuam. Quando você atinge uma criatura com um ataque de oportunidade, a velocidade dela se torna 0 pelo restante do turno. Criaturas a até 1,5m provocam ataques de oportunidade mesmo se usarem Desengajar. Quando um adversário ataca um aliado a até 1,5m, você usa sua reação para atacá-lo.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "grantsReaction": true, "actionName": "Retalia\u00e7\u00e3o Sentinela", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000723', 'SRD_2024', 'sharpshooter-2024', 'Sharpshooter', 'Franco-Atirador', 'Nível 4+, Destreza 13+', 'Você domina armas à distância. Atacar no alcance longo não impõe desvantagem em suas jogadas de ataque à distância. Seus ataques à distância ignoram meia cobertura e três quartos de cobertura. Disparar a até 1,5 metro de uma criatura hostil não impõe desvantagem.', 'SRD', 'GENERAL', '{"abilityBonuses": {"DEX": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "DEXTERITY", "minValue": 13, "displayLabel": "Destreza 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000724', 'SRD_2024', 'shield-master-2024', 'Shield Master', 'Mestre de Escudo', 'Nível 4+, Proficiência com Escudos', 'Você usa seu escudo não apenas para defesa, mas para agressão. Ao realizar a ação de Ataque em seu turno, você pode usar uma ação bônus para desferir um empurrão com escudo contra uma criatura a até 1,5m. Se for submetido a um efeito que permita uma salvaguarda de Destreza para metade do dano, use sua reação para não sofrer dano em caso de sucesso.', 'SRD', 'GENERAL', '{"abilityBonuses": {"STR": 1}, "actionName": "Empurr\u00e3o de Escudo", "actionType": "BONUS_ACTION", "grantsReaction": true, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000725', 'SRD_2024', 'skill-expert-2024', 'Skill Expert', 'Especialista em Perícia', 'Nível 4+', 'Você aprimorou suas habilidades excepcionalmente. Você ganha +1 em um atributo à sua escolha, ganha proficiência em uma perícia à sua escolha e ganha especialização (bônus de proficiência dobrado) em uma perícia em que você já seja proficiente.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX", "CON", "INT", "WIS", "CHA"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000726', 'SRD_2024', 'slasher-2024', 'Slasher', 'Cortador', 'Nível 4+, Força ou Destreza 13+', 'Você aprendeu a desferir cortes paralisantes. Uma vez por turno, ao acertar um ataque que cause dano cortante, você pode reduzir o deslocamento do alvo em 3 metros até o início do seu próximo turno. Ao obter um acerto crítico cortante, o alvo sofre desvantagem em todas as suas jogadas de ataque até o início do seu próximo turno.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000727', 'SRD_2024', 'skulker-2024', 'Skulker', 'Sorrateiro', 'Nível 4+, Destreza 13+', 'Especialista em espreitar pelas sombras. Você ganha visão no escuro em 3 metros (ou aumenta em 3 metros). Errar um ataque à distância enquanto estiver escondido não revela sua posição.', 'SRD', 'GENERAL', '{"abilityBonuses": {"DEX": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}, {"type": "ABILITY_SCORE", "targetKey": "DEXTERITY", "minValue": 13, "displayLabel": "Destreza 13+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000728', 'SRD_2024', 'mobile-2024', 'Speedy / Mobile', 'Velocista / Móvel', 'Nível 4+, Destreza ou Constituição 13+', 'Você é extraordinariamente veloz e ágil. Seu deslocamento aumenta em 3 metros (10 pés). Ao realizar a ação Correr, terreno difícil não custa movimento extra. Quando você realiza um ataque corpo a corpo contra uma criatura, você não provoca ataques de oportunidade dela pelo restante do turno.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["DEX", "CON"], "bonusAmount": 1}, "speedBonusFeet": 10, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000729', 'SRD_2024', 'spell-sniper-2024', 'Spell Sniper', 'Franco-Atirador de Magia', 'Nível 4+, Conjurador', 'Você dominou ataques mágicos à distância. Quando você conjura uma magia que requer uma jogada de ataque, o alcance dela é dobrado. Seus ataques mágicos ignoram meia cobertura e três quartos de cobertura. Estar a até 1,5m de um inimigo não impõe desvantagem em suas jogadas de ataque mágico.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS", "CHA"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000730', 'SRD_2024', 'telekinetic-2024', 'Telekinetic', 'Telecinético', 'Nível 4+', 'Você aprende o truque Mãos Mágicas, podendo conjurá-lo sem componentes verbais ou somáticos e tornando a mão invisível. Como ação bônus, você pode tentar empurrar telecineticamente uma criatura a até 9 metros por 1,5 metro em sua direção ou para longe (salvaguarda de Força).', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS", "CHA"], "bonusAmount": 1}, "actionName": "Empurr\u00e3o Telecin\u00e9tico", "actionType": "BONUS_ACTION", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000731', 'SRD_2024', 'telepathic-2024', 'Telepathic', 'Telepático', 'Nível 4+', 'Você desperta habilidades telepáticas. Você pode falar telepaticamente com qualquer criatura que você possa ver a até 18 metros. Você também pode conjurar a magia Detectar Pensamentos uma vez por descanso longo sem gastar espaços de magia.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS", "CHA"], "bonusAmount": 1}, "actionName": "Comunica\u00e7\u00e3o Telep\u00e1tica", "actionType": "FREE", "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('40000000-0000-0000-0000-000000000732', 'SRD_2024', 'weapon-master-2024', 'Weapon Master', 'Mestre em Armas', 'Nível 4+', 'Você praticou extensivamente com diversas armas. Você ganha mestria na propriedade de mestria de uma arma à sua escolha. Ao terminar um descanso longo, você pode trocar essa escolha de arma por outra.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "prerequisiteRules": [{"type": "LEVEL", "minValue": 4, "displayLabel": "N\u00edvel 4+"}]}'::jsonb),
    ('30000000-0000-0000-0000-000000000700', 'SRD_2014', 'actor-2014', 'Actor', 'Ator', NULL, 'Habilidoso em representação e mímica. +1 Carisma. Vantagem em testes de Enganação e Atuação ao tentar se passar por outra pessoa. Pode imitar a fala de outra criatura ou outros sons ouvidos por pelo menos 1 minuto.', 'SRD', 'GENERAL', '{"abilityBonuses": {"CHA": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000701', 'SRD_2014', 'alert-2014', 'Alert', 'Alerta', NULL, 'Sempre vigilante ao perigo. +5 de bônus em iniciativa. Você não pode ser surpreendido enquanto estiver consciente. Outras criaturas não ganham vantagem em jogadas de ataque contra você por estarem escondidas.', 'SRD', 'GENERAL', '{"initiativeBonus": 5}'::jsonb),
    ('30000000-0000-0000-0000-000000000702', 'SRD_2014', 'athlete-2014', 'Athlete', 'Atleta', NULL, 'Treinamento físico rigoroso. Levantar-se consome apenas 1,5m de movimento. Escalar não custa movimento extra. Saltar à distância ou em altura requer apenas 1,5m de corrida.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000703', 'SRD_2014', 'charger-2014', 'Charger', 'Investida', NULL, 'Ao usar a ação Correr, você pode usar uma ação bônus para fazer um ataque com arma corpo a corpo ou empurrar uma criatura. Se mover ao menos 3m em linha reta, ganha +5 de bônus no dano ou empurra até 3m.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000704', 'SRD_2014', 'crossbow-expert-2014', 'Crossbow Expert', 'Especialista em Besta', NULL, 'Você ignora a propriedade de recarga de bestas nas quais é proficiente. Estar a até 1,5m de um inimigo não impõe desvantagem em ataques à distância. Ao atacar com uma arma de uma mão, use ação bônus para atacar com besta de mão carregada.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000705', 'SRD_2014', 'defensive-duelist-2014', 'Defensive Duelist', 'Duelista Defensivo', 'Destreza 13+', 'Ao empunhar uma arma de acuidade e ser atingido por um ataque corpo a corpo, use sua reação para adicionar seu bônus de proficiência à sua CA contra o ataque.', 'SRD', 'GENERAL', '{"grantsReaction": true, "actionName": "Aparar Duelista", "prerequisiteRules": [{"type": "ABILITY_SCORE", "targetKey": "DEXTERITY", "minValue": 13, "displayLabel": "Destreza 13+"}]}'::jsonb),
    ('30000000-0000-0000-0000-000000000706', 'SRD_2014', 'dual-wielder-2014', 'Dual Wielder', 'Combatente com Duas Armas', NULL, '+1 na CA enquanto empunhar uma arma corpo a corpo em cada mão. Pode usar combate com duas armas mesmo se as armas não forem leves. Pode sacar ou embainhar duas armas simultaneamente.', 'SRD', 'GENERAL', '{"acBonus": 1}'::jsonb),
    ('30000000-0000-0000-0000-000000000707', 'SRD_2014', 'dungeon-delver-2014', 'Dungeon Delver', 'Explorador de Masmorras', NULL, 'Vantagem em Percepção e Investigação para detectar portas secretas e armadilhas. Vantagem em salvaguardas contra armadilhas e resistência ao dano causado por elas.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000708', 'SRD_2014', 'durable-2014', 'Durable', 'Robusto', NULL, '+1 Constituição. Ao rolar um dado de vida para recuperar pontos de vida em um descanso, o valor mínimo recuperado é igual ao dobro do seu modificador de Constituição (mínimo 2).', 'SRD', 'GENERAL', '{"abilityBonuses": {"CON": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000709', 'SRD_2014', 'elemental-adept-2014', 'Elemental Adept', 'Adepto Elemental', 'Capacidade de conjurar ao menos uma magia', 'Magias conjuradas ignoram resistência ao tipo de dano escolhido (Ácido, Frio, Fogo, Relâmpago ou Trovão). 1s em dados de dano daquele elemento contam como 2.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000710', 'SRD_2014', 'great-weapon-master-2014', 'Great Weapon Master', 'Mestre de Armas Grandes', NULL, 'Em seu turno, ao obter acerto crítico com arma corpo a corpo ou reduzir criatura a 0 PV, faça um ataque como ação bônus. Pode escolher sofrer -5 na jogada de ataque com arma pesada para causar +10 de dano se acertar.', 'SRD', 'GENERAL', '{"actionName": "Ataque Pesado (-5/+10)", "actionType": "FREE"}'::jsonb),
    ('30000000-0000-0000-0000-000000000711', 'SRD_2014', 'healer-2014', 'Healer', 'Curandeiro', NULL, 'Ao usar um kit de curandeiro para estabilizar uma criatura caída, ela recupera 1 PV. Como ação, use o kit para restaurar 1d6 + 4 + número de dados de vida máximos da criatura (uma vez por descanso por criatura).', 'SRD', 'GENERAL', '{"actionName": "Tratamento de Curandeiro", "actionType": "ACTION"}'::jsonb),
    ('30000000-0000-0000-0000-000000000712', 'SRD_2014', 'heavily-armored-2014', 'Heavily Armored', 'Armadura Pesada', 'Proficiência com armadura média', '+1 Força. Você ganha proficiência com armaduras pesadas.', 'SRD', 'GENERAL', '{"abilityBonuses": {"STR": 1}, "grantedProficiencies": ["ARMADURAS_PESADAS"]}'::jsonb),
    ('30000000-0000-0000-0000-000000000713', 'SRD_2014', 'heavy-armor-master-2014', 'Heavy Armor Master', 'Mestre de Armadura Pesada', 'Proficiência com armadura pesada', '+1 Força. Enquanto veste armadura pesada, o dano cortante, perfurante e de concussão de armas não mágicas é reduzido em 3.', 'SRD', 'GENERAL', '{"abilityBonuses": {"STR": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000714', 'SRD_2014', 'inspiring-leader-2014', 'Inspiring Leader', 'Líder Inspirador', 'Carisma 13+', 'Pode passar 10 minutos discursando para inspirar companheiros. Escolha até seis criaturas a até 9m: cada uma ganha PV temporários iguais a nível + modificador de Carisma.', 'SRD', 'GENERAL', '{"prerequisiteRules": [{"type": "ABILITY_SCORE", "targetKey": "CHARISMA", "minValue": 13, "displayLabel": "Carisma 13+"}]}'::jsonb),
    ('30000000-0000-0000-0000-000000000715', 'SRD_2014', 'keen-mind-2014', 'Keen Mind', 'Mente Aguçada', NULL, '+1 Inteligência. Sempre sabe para onde é o norte, sabe o número de horas até o próximo nascer ou pôr do sol e se lembra com precisão de tudo o que viu ou ouviu no último mês.', 'SRD', 'GENERAL', '{"abilityBonuses": {"INT": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000716', 'SRD_2014', 'lightly-armored-2014', 'Lightly Armored', 'Armadura Leve', NULL, '+1 Força ou Destreza. Você ganha proficiência com armaduras leves.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "grantedProficiencies": ["ARMADURAS_LEVES"]}'::jsonb),
    ('30000000-0000-0000-0000-000000000717', 'SRD_2014', 'lucky-2014', 'Lucky', 'Sortudo', NULL, 'Você tem 3 pontos de sorte. Ao rolar d20 para ataque, salvaguarda ou teste de atributo, gaste 1 ponto para rolar d20 adicional e escolher o resultado. Recarrega em descanso longo.', 'SRD', 'GENERAL', '{"usesPerRest": 3, "restType": "LONG", "actionName": "Ponto de Sorte", "actionType": "FREE"}'::jsonb),
    ('30000000-0000-0000-0000-000000000718', 'SRD_2014', 'mage-slayer-2014', 'Mage Slayer', 'Matador de Magos', NULL, 'Ao ver criatura a até 1,5m conjurar magia, use reação para desferir ataque corpo a corpo contra ela. Ao causar dano a criatura concentrando em magia, ela tem desvantagem na salvaguarda de concentração. Vantagem em salvaguardas contra magias conjuradas a até 1,5m.', 'SRD', 'GENERAL', '{"grantsReaction": true, "actionName": "Golpe Anti-Magia"}'::jsonb),
    ('30000000-0000-0000-0000-000000000719', 'SRD_2014', 'magic-initiate-2014', 'Magic Initiate', 'Iniciado em Magia', NULL, 'Escolha uma classe (Bardo, Clérigo, Druida, Feiticeiro, Bruxo ou Mago). Você aprende dois truques e uma magia de 1º círculo dessa classe, podendo conjurá-la uma vez por descanso longo.', 'SRD', 'GENERAL', '{"spellChoice": {"cantripsCount": 2, "spellsCount": 1, "spellLevel": 1, "allowedClasses": ["BARD", "CLERIC", "DRUID", "SORCERER", "WARLOCK", "WIZARD"]}}'::jsonb),
    ('30000000-0000-0000-0000-000000000720', 'SRD_2014', 'martial-adept-2014', 'Martial Adept', 'Adepto Marcial', NULL, 'Você aprende duas manobras da lista do Mestre da Batalha e ganha um dado de superioridade d6 que se recupera após um descanso curto ou longo.', 'SRD', 'GENERAL', '{"diceFormula": "1d6", "usesPerRest": 1, "restType": "SHORT"}'::jsonb),
    ('30000000-0000-0000-0000-000000000721', 'SRD_2014', 'medium-armor-master-2014', 'Medium Armor Master', 'Mestre de Armadura Média', 'Proficiência com armadura média', 'Usar armadura média não impõe desvantagem em testes de Furtividade. O bônus máximo de Destreza que pode adicionar à CA em armadura média sobe para +3.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000722', 'SRD_2014', 'mobile-2014', 'Mobile', 'Móvel', NULL, '+3m (10 pés) de deslocamento. Ao realizar a ação Correr, terreno difícil não custa movimento extra. Ao fazer um ataque corpo a corpo contra uma criatura, você não provoca ataques de oportunidade dela pelo restante do turno.', 'SRD', 'GENERAL', '{"speedBonusFeet": 10}'::jsonb),
    ('30000000-0000-0000-0000-000000000723', 'SRD_2014', 'moderately-armored-2014', 'Moderately Armored', 'Armadura Média', 'Proficiência com armadura leve', '+1 Força ou Destreza. Você ganha proficiência com armaduras médias e escudos.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}, "grantedProficiencies": ["ARMADURAS_MEDIAS", "ESCUDOS"]}'::jsonb),
    ('30000000-0000-0000-0000-000000000724', 'SRD_2014', 'mounted-combatant-2014', 'Mounted Combatant', 'Combatente Montado', NULL, 'Vantagem em ataques corpo a corpo contra alvos desmontados menores que sua montaria. Pode forçar ataques contra a montaria a alvejar você. Se a montaria fizer salvaguarda de Dex para metade do dano, não sofre dano em sucesso e metade em falha.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000725', 'SRD_2014', 'observant-2014', 'Observant', 'Observador', NULL, '+1 Inteligência ou Sabedoria. +5 de bônus em Percepção Passiva e Investigação Passiva. Se puder ver a boca de uma criatura falando em um idioma que você conhece, pode ler seus lábios.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["INT", "WIS"], "bonusAmount": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000726', 'SRD_2014', 'polearm-master-2014', 'Polearm Master', 'Mestre de Armas de Haste', NULL, 'Ao atacar com glaive, alabarda ou bordão, use ação bônus para atacar com a outra extremidade (1d4 concussão). Criaturas provocam ataque de oportunidade ao entrar no alcance de sua arma de haste.', 'SRD', 'GENERAL', '{"actionName": "Golpe da Extremidade", "actionType": "BONUS_ACTION", "diceFormula": "1d4"}'::jsonb),
    ('30000000-0000-0000-0000-000000000727', 'SRD_2014', 'resilient-2014', 'Resilient', 'Resiliente', NULL, 'Escolha um atributo. +1 no valor desse atributo e ganha proficiência nas salvaguardas que usam o atributo escolhido.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX", "CON", "INT", "WIS", "CHA"], "bonusAmount": 1}}'::jsonb),
    ('30000000-0000-0000-0000-000000000728', 'SRD_2014', 'ritual-caster-2014', 'Ritual Caster', 'Conjurador de Rituais', 'Inteligência ou Sabedoria 13+', 'Você adquire um livro de rituais com duas magias de 1º círculo com o descritor ritual da classe escolhida. Pode transcrever novos rituais encontrados durante as aventuras.', 'SRD', 'GENERAL', '{"spellChoice": {"cantripsCount": 0, "spellsCount": 2, "spellLevel": 1, "allowedClasses": ["BARD", "CLERIC", "DRUID", "SORCERER", "WARLOCK", "WIZARD"], "isRitualOnly": true}, "prerequisiteRules": [{"type": "ABILITY_SCORE", "targetKey": "INT_OR_WIS", "minValue": 13, "displayLabel": "Intelig\u00eancia ou Sabedoria 13+"}]}'::jsonb),
    ('30000000-0000-0000-0000-000000000729', 'SRD_2014', 'savage-attacker-2014', 'Savage Attacker', 'Atacante Selvagem', NULL, 'Uma vez por turno ao rolar dano de um ataque corpo a corpo com arma, você pode rolar o dano novamente e escolher o resultado maior.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000730', 'SRD_2014', 'sentinel-2014', 'Sentinel', 'Sentinela', NULL, 'Ataques de oportunidade reduzem o deslocamento do alvo a 0. Criaturas provocam ataques de oportunidade mesmo se usarem Desengajar. Se uma criatura a até 1,5m atacar um aliado adjacente, você pode usar sua reação para fazer um ataque corpo a corpo contra ela.', 'SRD', 'GENERAL', '{"grantsReaction": true, "actionName": "Retalia\u00e7\u00e3o de Sentinela"}'::jsonb),
    ('30000000-0000-0000-0000-000000000731', 'SRD_2014', 'sharpshooter-2014', 'Sharpshooter', 'Franco-Atirador', NULL, 'Atacar à distância longa não impõe desvantagem. Seus ataques à distância com armas ignoram meia cobertura e três quartos de cobertura. Antes de fazer um ataque com arma à distância em que seja proficiente, pode escolher sofrer -5 no ataque para causar +10 no dano.', 'SRD', 'GENERAL', '{"actionName": "Tiro Preciso (-5/+10)", "actionType": "FREE"}'::jsonb),
    ('30000000-0000-0000-0000-000000000732', 'SRD_2014', 'shield-master-2014', 'Shield Master', 'Mestre de Escudo', NULL, 'Ao realizar a ação Ataque em seu turno, use ação bônus para empurrar criatura a até 1,5m com o escudo. Adicione o bônus da CA do escudo a qualquer salvaguarda de Destreza contra magias que alvejem apenas você. Reação para dano zero em sucesso na salvaguarda de Dex.', 'SRD', 'GENERAL', '{"actionName": "Empurr\u00e3o de Escudo", "actionType": "BONUS_ACTION", "grantsReaction": true}'::jsonb),
    ('30000000-0000-0000-0000-000000000733', 'SRD_2014', 'skilled-2014', 'Skilled', 'Habilidoso', NULL, 'Você ganha proficiência em qualquer combinação de três perícias ou ferramentas à sua escolha.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000734', 'SRD_2014', 'skulker-2014', 'Skulker', 'Sorrateiro', 'Destreza 13+', 'Você pode tentar se esconder mesmo estando apenas levemente obscurecido. Errar um ataque à distância não revela sua posição quando escondido. Penumbra não impõe desvantagem em seus testes de Sabedoria (Percepção) baseados em visão.', 'SRD', 'GENERAL', '{"prerequisiteRules": [{"type": "ABILITY_SCORE", "targetKey": "DEXTERITY", "minValue": 13, "displayLabel": "Destreza 13+"}]}'::jsonb),
    ('30000000-0000-0000-0000-000000000735', 'SRD_2014', 'spell-sniper-2014', 'Spell Sniper', 'Franco-Atirador de Magia', 'Capacidade de conjurar ao menos uma magia', 'Ao conjurar magia que requer jogada de ataque, o alcance da magia é dobrado. Ataques mágicos à distância ignoram meia cobertura e três quartos de cobertura. Você aprende um truque que requer jogada de ataque de qualquer classe de conjurador.', 'SRD', 'GENERAL', '{}'::jsonb),
    ('30000000-0000-0000-0000-000000000736', 'SRD_2014', 'tavern-brawler-2014', 'Tavern Brawler', 'Brigão de Taverna', NULL, '+1 Força ou Constituição. Proficiente com armas improvisadas. Ataque desarmado causa 1d4 de dano. Ao atingir criatura com ataque desarmado ou arma improvisada em seu turno, pode usar ação bônus para tentar agarrar o alvo.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "CON"], "bonusAmount": 1}, "diceFormula": "1d4", "actionName": "Agarrar com A\u00e7\u00e3o B\u00f4nus", "actionType": "BONUS_ACTION"}'::jsonb),
    ('30000000-0000-0000-0000-000000000737', 'SRD_2014', 'tough-2014', 'Tough', 'Vigoroso', NULL, 'Seus pontos de vida máximos aumentam em um valor igual ao dobro do seu nível atual quando você adquire este talento. Toda vez que você subir de nível depois disso, ganha 2 pontos de vida adicionais.', 'SRD', 'GENERAL', '{"hpPerLevelBonus": 2}'::jsonb),
    ('30000000-0000-0000-0000-000000000738', 'SRD_2014', 'war-caster-2014', 'War Caster', 'Conjurador de Batalha', 'Capacidade de conjurar ao menos uma magia', 'Vantagem em salvaguardas de Constituição para manter concentração em magias ao sofrer dano. Pode realizar componentes somáticos de magias mesmo empunhando armas ou escudo em ambas as mãos. Pode usar sua reação para conjurar uma magia no lugar de um ataque de oportunidade.', 'SRD', 'GENERAL', '{"grantsReaction": true, "actionName": "Magia como Rea\u00e7\u00e3o"}'::jsonb),
    ('30000000-0000-0000-0000-000000000739', 'SRD_2014', 'weapon-master-2014', 'Weapon Master', 'Mestre em Armas', NULL, '+1 Força ou Destreza. Você ganha proficiência com quatro armas simples ou marciais à sua escolha.', 'SRD', 'GENERAL', '{"abilityBonusChoice": {"chooseCount": 1, "allowedAbilities": ["STR", "DEX"], "bonusAmount": 1}}'::jsonb)
