-- Migration V26: Seed Complete SRD General and Origin Feats (SRD 2014 & SRD 2024)
-- player-character-service

CREATE SCHEMA IF NOT EXISTS player_character;

-- 1. Normalize existing SRD 2024 Origin Feats (V14 created them with default GENERAL)
UPDATE player_character.feats
SET feat_type = 'ORIGIN',
    mechanical_effects = jsonb_set(
      jsonb_set(mechanical_effects, '{featType}', '"ORIGIN"'::jsonb),
      '{spellChoice}', '{"cantripsCount": 2, "spellsCount": 1, "spellLevel": 1, "allowedClasses": ["CLERIC", "DRUID", "WIZARD"]}'::jsonb
    )
WHERE slug = 'magic-initiate-2024' AND ruleset = 'SRD_2024';

UPDATE player_character.feats
SET feat_type = 'ORIGIN',
    mechanical_effects = jsonb_set(mechanical_effects, '{featType}', '"ORIGIN"'::jsonb)
WHERE slug IN ('savage-attacker-2024', 'skilled-2024') AND ruleset = 'SRD_2024';

-- 2. Insert Missing SRD 2024 Origin, SRD 2024 General, and SRD 2014 General Feats
ON CONFLICT (ruleset, slug) DO UPDATE SET
    name_en = EXCLUDED.name_en,
    name = EXCLUDED.name,
    prerequisites = EXCLUDED.prerequisites,
    description = EXCLUDED.description,
    feat_type = EXCLUDED.feat_type,
    mechanical_effects = EXCLUDED.mechanical_effects;
